import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

// Dev: Vite on 5173 proxies /api to the FastAPI server on 8000.
// Never run the dev server while tests or benchmarks are running (8 GB laptop).
//
// `vite build --mode showcase` builds the hosted, backend-free site into dist-showcase/.
// Its public folder, showcase-public/, is generated by scripts/build_showcase.py: a copy of
// public/ (favicons, fonts) plus a snapshot of real data and the demo video. Neither folder
// is committed.
export default defineConfig(({ mode }) => {
  const showcase = mode === "showcase";
  return {
    plugins: [react(), tailwindcss()],
    publicDir: showcase ? "showcase-public" : "public",
    server: {
      host: "127.0.0.1",
      port: 5173,
      strictPort: true,
      proxy: { "/api": "http://127.0.0.1:8000" },
    },
    build: {
      outDir: showcase ? "dist-showcase" : "dist",
      emptyOutDir: true,
      chunkSizeWarningLimit: 600,
    },
  };
});
